mapper.select:
WITH RECURSIVE category_tree AS ( -- 起始节点：父分类自身 SELECT category_id, category_code, parent_id FROM product_category WHERE category_id = #{ancestorId}
UNION ALL
-- 递归查询子节点：子分类的parent_id = 父分类的category_id SELECT pc.category_id, pc.category_code, pc.parent_id FROM product_category pc INNER JOIN category_tree ct ON pc.parent_id = ct.category_id ) -- 提取所有层级的category_code SELECT category_code FROM category_tree;
